#include "stdlib/math/base/special/sqrt.h"
#include "stdlib/ndarray/base/unary.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define NAME "sqrt"
#define ITERATIONS 10000000
#define REPEATS 3
#define MIN 1
#define MAX 6

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total );
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmark results.
*
* @param iterations   number of iterations
* @param elapsed      elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Generates a random number on the interval [-pi, pi].
*
* @return random number
*/
static double rand_double( void ) {
	int r = rand();
	return ( (double)r / ( (double)RAND_MAX + 1.0 ) * 6.28318530718 ) - 3.14159265359;
}

/**
* Runs a benchmark.
*
* @param iterations  number of iterations
* @param len         array length
* @return elapsed time in seconds
*/
static double benchmark( int iterations, int len ) {
	double elapsed;
	double t;
	double v;
	int i;

	// Allocate and initialize the input ndarray data buffer:
	double *xbuf = (double *) malloc( len * sizeof( double ) );
	if ( xbuf == NULL ) {
		printf( "Failed to allocate an input ndarray buffer\n" );
		return 0.0;
	}
	for ( i = 0; i < len; i++ ) {
		xbuf[ i ] = rand_double();
	}
	// Cast the input ndarray data buffer to a byte buffer:
	uint8_t *xb = (uint8_t *)xbuf;

	// Define ndarray meta data:
	const enum STDLIB_NDARRAY_DTYPE dtype = STDLIB_NDARRAY_FLOAT64;
	const int64_t ndims = 1;
	int64_t shape[] = { len };
	int64_t strides[] = { STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT };
	const int64_t offset = 0;
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	const int64_t nsubmodes = 1;

	// Allocate the input ndarray:
	struct ndarray *x = stdlib_ndarray_allocate( dtype, xb, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );
	if ( x == NULL ) {
		printf( "Failed to allocate an input ndarray\n" );
		return 0.0 / 0.0; // NaN
	}

	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		// Allocate an output ndarray data buffer:
		double *ybuf = (double *) malloc( len * sizeof( double ) );
		if ( ybuf == NULL ) {
			printf( "Failed to allocate an output ndarray buffer\n" );
			break;
		}
		// Cast the output ndarray data buffer to a byte buffer:
		uint8_t *yb = (uint8_t *)ybuf;

		// Allocate an output ndarray:
		struct ndarray *y = stdlib_ndarray_allocate( dtype, yb, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );
		if ( y == NULL ) {
			printf( "Failed to allocate an output ndarray\n" );
			free( ybuf );
			break;
		}
		// Define an array containing the input and output ndarray:
		struct ndarray *arrays[] = { x, y };

		// Perform computation:
		int8_t status = stdlib_ndarray_d_d( arrays, (void *)stdlib_base_sqrt );
		if ( status != 0 ) {
			printf( "Unexpected error\n" );
			free( ybuf );
			stdlib_ndarray_free( y );
			break;
		}
		// Retrieve an element from the output array:
		stdlib_ndarray_iget_float64( y, i%len, &v );
		if ( v != v ) {
			printf( "should not return NaN\n" );
			free( ybuf );
			stdlib_ndarray_free( y );
			break;
		}
		// Free the resources associated with the output ndarray:
		free( ybuf );
		stdlib_ndarray_free( y );
	}
	elapsed = tic() - t;

	if ( v != v ) {
		printf( "should not return NaN\n" );
	}
	// Free the resources associated with the input ndarray:
	free( xbuf );
	stdlib_ndarray_free( x );

	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;
	int j;

	// Use the current time to seed the random number generator:
	srand( time( NULL ) );

	print_version();
	count = 0;
	for ( i = MIN; i <= MAX; i++ ) {
		len = pow( 10, i );
		iter = ITERATIONS / pow( 10, i-1 );
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:contiguous=true,ndims=1,dtype=float64,size=%d\n", NAME, len );
			elapsed = benchmark( iter, len );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	print_summary( count, count );
}
